sub:Head {
  : np:hasAssertion sub:assertion;
    np:hasProvenance sub:provenance;
    np:hasPublicationInfo sub:pubinfo;
    a np:Nanopublication .
}

sub:assertion {
  sub:userstory a <https://w3id.org/fff/User-Story>;
    rdfs:label "test";
    <https://w3id.org/fff/as-a> "a knowledge broker";
    <https://w3id.org/fff/i-want-to> "find stories";
    <https://w3id.org/fff/so-that> "I can reuse them" .
}

sub:provenance {
  sub:assertion prov:wasAttributedTo <https://w3id.org/np/RAIA9ECaN2ypOVvl4YeNjT6nbpwko9xMcctxB_uYscLG4/claude-ai-agent> .
  sub:assertion prov:wasGeneratedBy <https://w3id.org/fair2adapt/matchmaker-form> .
}

sub:pubinfo {
  : dct:created "2026-11-20T22:49:06.001Z"^^xsd:dateTime;
    dct:creator <https://orcid.org/0000-0002-1784-2920>;
    dct:license <https://creativecommons.org/licenses/by/4.0/>;
    rdfs:label "test";
    npx:introduces sub:userstory;
    npx:wasCreatedAt <https://w3id.org/fair2adapt/matchmaker-form>;
